      html += '<li class="stage-option' + (o.correct ? ' is-correct' : '') + '"><span class="stage-option__bar" style="--share: ' + pct + '%"></span><span class="stage-option__letter">' + letter + '</span><span class="stage-option__title">' + esc(o.text) + '</span><span class="stage-option__count">' + o.count + '</span>' + (o.correct ? '<span class="stage-option__mark">Correct</span>' : '') + '</li>';
    }
    html += '</ol><div class="counter-pill" id="answers-counter">Answers: ' + s.answers_count + ' / ' + s.players_count + '</div>';
    return html;
  }
  function renderEndedBody(s) {
    var html = '<div class="stage-question__body">The quiz is over</div>';
    var board = (s && s.leaderboard) ? s.leaderboard : [];
    if (board && board.length > 0) {
      html += '<ol class="leaderboard" id="leaderboard">';
      for (var i = 0; i < board.length; i++) {
        var r = board[i];
        html += '<li class="leader' + (r.is_winner ? ' is-winner' : '') + '">' +
          '<span class="leader__place">' + esc(r.place) + '</span>' +
          '<span class="leader__name">' + esc(r.name) + (r.is_winner ? '<span class="leader__badge">Winner</span>' : '') + '</span>' +
          '<span class="leader__score">' + esc(r.points_text) + '</span>' +
          '</li>';
      }
      html += '</ol>';
    }
    return html;
  }
  function renderActions(s) {
    var token = csrfToken();
    function form(url, label, cls) {
      var c = cls || "btn btn--pink btn--lg";
      return '<form action="' + url + '" method="post" data-turbo="false"><input type="hidden" name="authenticity_token" value="' + esc(token) + '"><button type="submit" class="' + c + '">' + esc(label) + '</button></form>';
    }
