        fullRender(s);
        lastStatus = s.status;
        lastQuestionId = qid;
        lastPlayers = s.players_count;
        lastAnswers = s.answers_count || 0;
        lastTotal = s.total || 0;
        lastNum = s.current_num || 0;
        lastBoardKey = key;
        return;
      }
      return;
    }
    if (statusChanged || questionChanged || totalChanged || numChanged) {
      fullRender(s);
      lastStatus = s.status;
      lastQuestionId = qid;
      lastPlayers = s.players_count;
      lastAnswers = s.answers_count || 0;
      lastTotal = s.total || 0;
      lastNum = s.current_num || 0;
      lastBoardKey = null;
