  (function() {
    var stateUrl = "<%= play_state_path(code: @game.code) %>";
    var answerUrl = "<%= play_answer_path(code: @game.code) %>";
    var lastStatus = <%= raw @game.status.to_json %>;
    var lastQuestionId = <%= raw((@question&.id).to_json) %>;
    var lastPicked = <%= raw((@picked_option_id).to_json) %>;
    var lastFeedback = <%= raw((@feedback).to_json) %>;
    var lastPlace = null;
    var lastPoints = null;
    var lastWon = null;
    var playerName = <%= raw @player.name.to_s.to_json %>;

    function esc(s) {
      return String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
    }
    function csrfToken() {
      var m = document.querySelector('meta[name="csrf-token"]');
      return m ? m.content : "";
    }

    function renderLobby(s) {
      return '<div class="waiting"><div class="waiting__gem">?</div><div class="play-title">Hi, ' + esc(s.player_name) + '!</div><div class="play-lead">Waiting for the quiz to start...</div></div>';
    }
    function renderOpen(s) {
      var q = s.question;
      var html = '<div class="play-question__num">Question ' + s.current_num + ' of ' + s.total + '</div>' +
        '<div class="play-question__body">' + esc(q.body) + '</div>' +
        '<div class="play-options" id="play-options">';
      for (var i = 0; i < q.options.length; i++) {
        var o = q.options[i];
        var letter = String.fromCharCode(65 + i);
        var picked = (s.picked_option_id != null && s.picked_option_id === o.id);
        html += '<form action="' + answerUrl + '" method="post" data-turbo="false" data-option-form data-option-id="' + o.id + '">' +
          '<input type="hidden" name="option_id" value="' + o.id + '">' +
          '<button type="submit" class="play-option' + (picked ? ' is-picked' : '') + '">' +
          '<span class="play-option__letter">' + letter + '</span>' +
          '<span class="play-option__title">' + esc(o.text) + '</span>' +
          (picked ? '<span class="play-option__mark">Your answer</span>' : '') +
          '</button></form>';
      }
      html += '</div>';
      return html;
    }
    function renderClosed(s) {
      var q = s.question;
      var fb = s.feedback || "";
      var klass = s.feedback_class || "play-status--neutral";
      return '<div class="play-question__num">Question ' + s.current_num + ' of ' + s.total + '</div>' +
        '<div class="play-question__body">' + esc(q.body) + '</div>' +
        '<div class="play-status ' + klass + '">' + esc(fb) + '</div>';
    }
    function renderEnded(s) {
      var html = '<div class="play-title">The quiz is over</div>';
      if (s && s.place_text && s.points_text) {
        html += '<div class="result-card"><div class="result-card__label" id="player-place">' + esc(s.place_text) + '</div>' +
          '<div class="result-card__score" id="player-points">' + esc(s.points_text) + '</div></div>';
      }
      if (s && s.won) {
        html += '<div class="winner-banner" id="winner-banner">You won!</div>';
      }
      return html;
    }

    function bindAnswerForms() {
      var forms = document.querySelectorAll('[data-option-form]');
      for (var i = 0; i < forms.length; i++) {
        (function(f) {
          if (f.dataset.bound) return;
          f.dataset.bound = "1";
          f.addEventListener("submit", function(e) {
            e.preventDefault();
            var optId = f.getAttribute("data-option-id");
            // Optimistic update: mark immediately for snappy feel on crowded Wi-Fi
            try {
              var btns = document.querySelectorAll('#play-options .play-option');
              for (var b = 0; b < btns.length; b++) {
                btns[b].classList.remove('is-picked');
                var mk = btns[b].querySelector('.play-option__mark');
                if (mk) mk.remove();
              }
              var btn = f.querySelector('button.play-option');
              if (btn) {
                btn.classList.add('is-picked');
                if (!btn.querySelector('.play-option__mark')) {
                  var span = document.createElement('span');
                  span.className = 'play-option__mark';
                  span.textContent = 'Your answer';
                  btn.appendChild(span);
                }
              }
            } catch(err) {}
            postAnswer(optId);
          });
        })(forms[i]);
      }
    }

    function postAnswer(optionId) {
      var token = csrfToken();
      var body = "option_id=" + encodeURIComponent(optionId);
      fetch(answerUrl, {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded", "X-CSRF-Token": token, "X-Requested-With": "XMLHttpRequest", "Accept": "application/json" },
        body: body,
        credentials: "same-origin"
      }).then(function() { poll(); }).catch(function() {});
    }

    function fullRender(s) {
      var body = document.getElementById("play-body");
      if (!body) return;
      if (s.status === "lobby") body.innerHTML = renderLobby(s);
      else if (s.status === "open") body.innerHTML = renderOpen(s);
      else if (s.status === "closed") body.innerHTML = renderClosed(s);
      else if (s.status === "ended") body.innerHTML = renderEnded(s);
      bindAnswerForms();
    }

    function handleState(s) {
      // If server says not joined (cookie lost), reload to show join form
      if (!s.joined) {
        // Only reload if we were joined (cookie expired?) - otherwise stay
        // For simplicity, reload page to show join form
        if (lastStatus !== "ended") window.location.reload();
        return;
      }
      if (s.status === "ended") {
        var placeText = s.place_text || null;
        var pointsText = s.points_text || null;
        var won = (s.won != null ? !!s.won : null);
        if (s.status !== lastStatus || placeText !== lastPlace || pointsText !== lastPoints || won !== lastWon) {
          fullRender(s);
          lastStatus = s.status;
          lastQuestionId = null;
          lastPicked = null;
          lastFeedback = null;
          lastPlace = placeText;
          lastPoints = pointsText;
          lastWon = won;
          var g = document.getElementById("player-greeting");
          if (g && s.player_name) g.textContent = "Hi, " + s.player_name + "!";
        }
        return;
      }
      var qid = s.question ? s.question.id : null;
      var picked = (s.picked_option_id != null ? s.picked_option_id : null);
      var fb = s.feedback || null;
      if (s.status !== lastStatus || qid !== lastQuestionId || picked !== lastPicked || fb !== lastFeedback) {
        fullRender(s);
        lastStatus = s.status;
        lastQuestionId = qid;
        lastPicked = picked;
        lastFeedback = fb;
        lastPlace = null;
        lastPoints = null;
        lastWon = null;
        // Update greeting if name changed (should not)
        var g2 = document.getElementById("player-greeting");
        if (g2 && s.player_name) g2.textContent = "Hi, " + s.player_name + "!";
      }
    }

    function poll() {
      fetch(stateUrl, { headers: { "Accept": "application/json" }, credentials: "same-origin", cache: "no-store" })
        .then(function(r) { if (!r.ok) return null; return r.json(); })
        .then(function(s) { if (s) handleState(s); })
        .catch(function() {});
    }

    bindAnswerForms();
    setInterval(poll, 400);
    setTimeout(poll, 150);
  })();
  </script>
<% end %>
